fun main() {
  val plain = "0d000721"
  val l1 = plain.reversed()
  val xored = l1.map { (it.code xor 0x5A).toByte() }.toByteArray()
  val l3 = xored.joinToString("") { "%02x".format(it) }
  val l4 = java.util.Base64.getEncoder().encodeToString(l3.toByteArray())
  println(l4.reversed())
}
